// Des: Tests for the AI adapter chain
// Flo: off = refuses > Claude CLI missing falls back to the llama.cpp mock > non-loopback url refused > JSON content parsed
// I/O: mock llama server on loopback + missing exe name (no real AI, no network) > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-smar-adap-test.zig
// ===================================================================
const std = @import("std"); const adap = @import("ru-smar-adap.zig"); const task = @import("ru-task-runn.zig"); const mockm = @import("te-mock-page.zig"); const stat = @import("st-stat-main.zig"); const pg = @import("ru-page-snap.zig"); const pace = @import("ru-huma-pace.zig");
fn mk(aren: std.mem.Allocator, conf: @import("cf-conf-load.zig").Conf, store: *stat.Stat, page: *pg.Page, rng: *pace.Rng) task.Ctx { return .{ .gpaz = std.testing.allocator, .aren = aren, .iozz = std.testing.io, .conf = conf, .store = store, .mode = .dry, .page = page, .rng = rng, .base = "" }; }
test "url split allows only loopback http with a port" { const sp = try adap.urlSplit("http://127.0.0.1:8080"); try std.testing.expectEqual(@as(u16, 8080), sp.port); _ = try adap.urlSplit("http://localhost:9/x"); try std.testing.expectError(error.AiFail, adap.urlSplit("http://example.com:80")); try std.testing.expectError(error.AiFail, adap.urlSplit("https://127.0.0.1:8080")); try std.testing.expectError(error.AiFail, adap.urlSplit("http://127.0.0.1")); }
test "content parse trims, refuses empty and bad json" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); try std.testing.expectEqualStrings("hi there", try adap.contentOf(aren.allocator(), "{\"content\":\"  hi there \\n\"}")); try std.testing.expectError(error.AiFail, adap.contentOf(aren.allocator(), "{\"content\":\"  \"}")); try std.testing.expectError(error.AiFail, adap.contentOf(aren.allocator(), "nope")); try std.testing.expectError(error.AiFail, adap.contentOf(aren.allocator(), "{\"x\":1}")); }
test "switch off refuses; missing Claude falls back to llama.cpp mock" { var mock: mockm.Mock = undefined; try mock.start(std.testing.io); defer mock.halt(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var conf: @import("cf-conf-load.zig").Conf = .{}; var store: stat.Stat = undefined; var page: pg.Page = undefined; var rng = pace.Rng.init(1); var cx = mk(aren.allocator(), conf, &store, &page, &rng); try std.testing.expectError(error.AiFail, adap.draftChain(&cx, "hello")); conf.smar_mode_enab = true; conf.smar_clau_exec = "zz-no-such-claude-exe"; conf.smar_llam_urlz = try std.fmt.allocPrint(aren.allocator(), "http://127.0.0.1:{d}", .{mock.port}); cx = mk(aren.allocator(), conf, &store, &page, &rng); try std.testing.expectEqualStrings("Sure, happy to help!", try adap.draftChain(&cx, "hello")); }
test "every tool failing gives AiFail" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var conf: @import("cf-conf-load.zig").Conf = .{}; conf.smar_mode_enab = true; conf.smar_clau_exec = "zz-no-such-claude-exe"; conf.smar_llam_urlz = "http://127.0.0.1:1"; var store: stat.Stat = undefined; var page: pg.Page = undefined; var rng = pace.Rng.init(1); var cx = mk(aren.allocator(), conf, &store, &page, &rng); try std.testing.expectError(error.AiFail, adap.draftChain(&cx, "hello")); }
